    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    def runs(sequence):
        result = []
        i = 0
        while i < len(sequence):
            if sequence[i] == bg:
                i += 1
                continue
            color, start = sequence[i], i
            while i < len(sequence) and sequence[i] == color:
                i += 1
            if i - start >= 2:
                result.append((start, i - 1, color))
        return result

    candidates = []
    for side, r in (("top", 0), ("bottom", h - 1)):
        for lo, hi, color in runs(grid[r]):
            candidates.append(("h", side, lo, hi, color))
    for side, c in (("left", 0), ("right", w - 1)):
        for lo, hi, color in runs([grid[r][c] for r in range(h)]):
            candidates.append(("v", side, lo, hi, color))

    pairs = []
    for i, first in enumerate(candidates):
        for second in candidates[i + 1:]:
            if (first[0] == second[0] and first[1] != second[1]
                    and first[4] == second[4]
                    and first[3] - first[2] == second[3] - second[2]):
                sides = {first[1], second[1]}
                if ((first[0] == "h" and sides == {"top", "bottom"})
                        or (first[0] == "v" and sides == {"left", "right"})):
                    pairs.append((first, second))
    if not pairs:
        return out
    bars = list(pairs[0])
    bar_cells = set()
    for orient, side, lo, hi, _ in bars:
        if orient == "h":
            edge = 0 if side == "top" else h - 1
            bar_cells.update((edge, c) for c in range(lo, hi + 1))
        else:
            edge = 0 if side == "left" else w - 1
            bar_cells.update((r, edge) for r in range(lo, hi + 1))
    extras = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and (r, c) not in bar_cells]

    for r, c, ray_color in extras:
