        offset = axis - source[2]
        for orient, side, lo, hi, _ in bars:
            coordinate = lo + offset
            if orient == "h":
                if side == "top":
                    current, step = 1, 1
                    limit = h if len(extras) == 1 else h - 1
                else:
                    current, step = h - 2, -1
                    limit = -1
                while current != limit:
                    value = grid[current][coordinate]
                    if value != bg:
                        out[current][coordinate] = 4
                        break
                    out[current][coordinate] = ray_color
                    current += step
            else:
                if side == "left":
                    current, step = 1, 1
                    limit = w if len(extras) == 1 else w - 1
                else:
                    current, step = w - 2, -1
                    limit = -1
